console.log(`Screen generated: ${screen.id}`);


// 3. Get your outputs
const htmlUrl = await screen.getHtml();
const imageUrl = await screen.getImage();


console.log(`HTML:  ${htmlUrl}`);
console.log(`Image: ${imageUrl}`);

